import { describe, expect, it } from 'vitest';
import { encodeAction, parseCatalog, parseCodex, parseServerMessage, ProtocolError, type ClientAction } from './messages';

// Generated by the server (ContractFixturesTest); never edit by hand.
const serverFixtures = import.meta.glob<string>('./fixtures/server/*.json',
  { eager: true, query: '?raw', import: 'default' });
// Owned by the client; the server's ContractFixturesTest parses them.
const clientFixtures = import.meta.glob<string>('./fixtures/client/*.json',
  { eager: true, query: '?raw', import: 'default' });

const name = (path: string) => path.replace(/^.*\//, '').replace(/\.json$/, '');
const fixture = (n: string): unknown => JSON.parse(serverFixtures[`./fixtures/server/${n}.json`] ?? 'null');

describe('server → client contract', () => {
  it('has a fixture for every message type', () => {
    expect(Object.keys(serverFixtures).map(name).sort()).toEqual(
      ['catalog', 'codex', 'error', 'paused', 'rejected', 'snapshot-burning', 'snapshot-chapter', 'snapshot-delta',
        'snapshot-incident', 'snapshot-keyframe', 'snapshot-postmortem', 'welcome']);
  });

  // catalog and codex are HTTP bodies, not socket messages.
  for (const path of Object.keys(serverFixtures).filter((p) => !['catalog', 'codex'].includes(name(p)))) {
    it(`parses ${name(path)} strictly`, () => {
      const message = parseServerMessage(fixture(name(path)));
      expect(name(path).startsWith(message.type)).toBe(true);
    });
  }

  it('keyframes carry the lists, deltas leave them out', () => {
    const key = parseServerMessage(fixture('snapshot-keyframe'));
    const delta = parseServerMessage(fixture('snapshot-delta'));
    expect(key.type === 'snapshot' && key.counters?.map((c) => c.id)).toEqual(['prometheus', 'grafana']);
    expect(delta.type === 'snapshot' && delta.counters).toBeUndefined();
  });

  it('rejects fields it does not know', () => {
    const raw = fixture('paused') as Record<string, unknown>;
    expect(() => parseServerMessage({ ...raw, surprise: 1 })).toThrow(ProtocolError);
  });

  it('parses the catalog sample strictly', () => {
    const catalog = parseCatalog(fixture('catalog'));
    expect(catalog.counters.map((c) => c.id))
      .toEqual(['prometheus', 'grafana', 'expand-disk', 'nginx-rate-limit', 'create-index']);
    expect(catalog.counters[4]?.options.map((o) => o.id)).toEqual(['blocking', 'concurrently']);
    expect(catalog.counters[2]?.removable).toBe(false);
    expect(catalog.counters[3]?.setting).toEqual({ key: 'rate_rps', value: 150, min: 50, max: 400 });
    expect(catalog.counters[3]?.nodes).toEqual(['gateway']); // a rate limiter answers at the edge
    expect(catalog.counters[0]?.nodes).toEqual([]);
    expect(catalog.counters[0]?.requiresInsight).toBeNull();
  });

  it('sends the postmortem question without its answer', () => {
    const s = parseServerMessage(fixture('snapshot-postmortem'));
    const pm = s.type === 'snapshot' ? s.postmortem : undefined;
    expect(pm?.questionKey).toBe('pm.log_storm.q');
    expect(pm?.options).toHaveLength(4);
    expect(pm?.correct).toBeNull();
  });

  it('sends the station capacities on keyframes', () => {
    const s = parseServerMessage(fixture('snapshot-keyframe'));
    expect(s.type === 'snapshot' && s.station?.threads).toBe(200);
  });

  it('sends alert rules with their state', () => {
    const s = parseServerMessage(fixture('snapshot-keyframe'));
    expect(s.type === 'snapshot' && s.alerts?.map((a) => [a.id, a.op, a.firingSinceTick])).toEqual([['a1', 'ABOVE', -1]]);
  });

  it('sends the crew and the incident actions it ran', () => {
    const s = parseServerMessage(fixture('snapshot-incident'));
    if (s.type !== 'snapshot') throw new Error('expected a snapshot');
    expect(s.crew).toBe(5);
    expect(s.actions?.map((a) => a.id)).toEqual(['clear-disk', 'restart-app']);
    expect(s.actions?.[0]?.option).toBe('rm');
    const catalog = parseCatalog(fixture('catalog'));
    expect(catalog.crewPerShift).toBe(8);
    expect(catalog.actions[0]?.options.map((o) => o.id)).toEqual(['truncate', 'archives', 'rm']);
  });

  it('sends how fast the shield burns', () => {
    const s = parseServerMessage(fixture('snapshot-burning'));
    expect(s.type === 'snapshot' && s.burnRate).toBeGreaterThan(1);
    expect(s.type === 'snapshot' && s.shieldEmptyInS).toBeGreaterThan(0);
  });

  it('sends wave results and the chapter summary once it is won', () => {
    const s = parseServerMessage(fixture('snapshot-chapter'));
    if (s.type !== 'snapshot') throw new Error('expected a snapshot');
    expect(s.results?.map((r) => r.wave)).toEqual([1, 2, 3, 4, 5]);
    expect(s.results?.[0]?.postmortemRight).toBeNull();
    expect(s.chapter?.postmortemsRight).toBe(4);
    expect(parseServerMessage(fixture('snapshot-keyframe'))).not.toHaveProperty('chapter');
  });

  it('parses the codex sample strictly', () => {
    const codex = parseCodex(fixture('codex'));
    expect(codex.entries.map((e) => e.id)).toEqual(['prometheus', 'use-method']);
    expect(codex.entries[0]?.body).toContain('\n\n'); // paragraphs
  });

  it('keyframes list the opened codex entries', () => {
    const key = parseServerMessage(fixture('snapshot-keyframe'));
    expect(key.type === 'snapshot' && key.codex).toEqual(['prometheus', 'use-method', 'dashboards', 'traffic-heatmap']);
  });

  it('keeps the 64-bit seed exact', () => {
    const big = { ...(fixture('welcome') as Record<string, unknown>), seed: '-7046029254386353131' };
    const welcome = parseServerMessage(big);
    expect(welcome.type === 'welcome' && welcome.seed).toBe('-7046029254386353131');
  });
});

describe('client → server contract', () => {
  const actions: Record<string, ClientAction> = {
    'start-wave': { type: 'start_wave', wave: 1 },
    'apply-counter': { type: 'apply_counter', counter: 'create-index', option: 'concurrently' },
    'answer-postmortem': { type: 'answer_postmortem', option: 'b' },
    'run-action': { type: 'run_action', action: 'clear-disk', option: 'truncate' },
    'remove-counter': { type: 'remove_counter', counter: 'prometheus' },
    'configure-counter': { type: 'configure_counter', counter: 'nginx-rate-limit', value: 300 },
    'set-alert': { type: 'set_alert', metric: 'cpu_utilization', op: 'ABOVE', threshold: 0.85, forS: 10 },
    'remove-alert': { type: 'remove_alert', rule: 'a1' },
    pause: { type: 'pause' },
    resume: { type: 'resume' },
  };

  for (const [path, raw] of Object.entries(clientFixtures)) {
    it(`encodes ${name(path)} exactly as the fixture`, () => {
      const action = actions[name(path)];
      if (action === undefined) throw new Error(`no action for fixture ${path}`);
      expect(encodeAction(action)).toBe(raw.trim());
    });
  }
});
